def verify():
 checks=[]
 def check(ok,text):
  checks.append(('PASS' if ok else 'FAIL',text))
 check([len(panels[s]) for s in folders]==[4,5,5,5,5,5,4], 'Existing V2 panel counts 4/5/5/5/5/5/4 (33).')
 check(len(rows)==22 and len({r[0] for r in rows})==22,'22 unique proposed shot IDs across S01–S07.')
 for s,budget in zip(folders,[10,12,18,18,12,12,8]):
  mapped=[n for r in rows if r[0].startswith(s) for n in r[1]]
  check(sorted(mapped)==list(range(1,len(panels[s])+1)),f'{s}: each existing panel maps exactly once.')
  check(sum(r[2] for r in rows if r[0].startswith(s))==budget,f'{s}: proposed durations fit inherited {budget}s budget.')
 check(sum(r[2] for r in rows)==90,'Proposed total = confirmed 90 seconds.')
 ids={b[0] for b in blockers}
 check(len(ids)==16 and all(len(b)==11 and all(b) for b in blockers),'16 unique blockers; all pinned fields populated plus decision references.')
 check(all(set(r[-1].split())<=ids for r in rows),'All shot blocker references resolve.')
 check(all(all(r[i] for i in range(3,10)) for r in rows),'All shots have mechanism/input/output, camera-transition intent, information beats and review need.')
 with (RECORDS/'panel-shot-map_v001.csv').open(encoding='utf-8',newline='') as f: data=list(csv.DictReader(f))
 check(len(data)==33 and all((ROOT/x['existing_panel_path']).is_file() and (ROOT/x['caption_or_narrative_path']).is_file() for x in data),'CSV: 33 saved panel rows; all exact panel/narrative paths exist.')
 files=[RECORDS/'shot-register_v001.md',RECORDS/'blocker-register_v001.md',TASK/'report.md',TASK/'review-summary_v001.md']
 links=0; bad=[]
 for p in files:
  if not p.exists(): bad.append(str(p)); continue
  for target in re.findall(r'\[[^\]]*\]\(([^)]+)\)',p.read_text(encoding='utf-8')):
   if '://' in target or target.startswith('#'): continue
   links+=1
   if not (p.parent/target.split('#')[0]).resolve().exists(): bad.append(f'{p.name}: {target}')
 check(not bad,f'All {links} local Markdown links resolve; missing={bad}.')
 manifest=json.loads((TASK/'Evidence/source-manifest_v001.json').read_text(encoding='utf-8'))
 drift=[x['path'] for x in manifest['sources'] if hashlib.sha256((ROOT/x['path']).read_bytes()).hexdigest()!=x['sha256']]
 check(not drift,'Inspected source hashes unchanged at verification; drift='+str(drift))
 for p in files:
  if p.exists():
   text=p.read_text(encoding='utf-8')
   check('\ufffd' not in text and not any(line.rstrip()!=line for line in text.splitlines()),f'{p.name}: UTF-8/no replacement characters/no trailing spaces.')
 status=subprocess.check_output(['git','status','--short'],cwd=ROOT,text=True)
 diff=subprocess.run(['git','diff','--check'],cwd=ROOT,capture_output=True,text=True)
 check(diff.returncode==0,'Tracked worktree whitespace check: '+(diff.stdout or diff.stderr or 'clean').strip())
 result=['# A03 verification v001','', 'Self-checks of saved text/CSV and source references; no independent engineering, camera-motion or render validation claimed.','']
 result += [f'- **{state}:** {message}' for state,message in checks]
 result += ['', '## Git snapshot', '', '```text',status.rstrip(),'```','', 'Existing T-001/T-002 records and context edits are unrelated/concurrent work. This task writes only the three versioned inventory outputs and T-003 records. No commit/push/publication or backup performed. No Blender scene was changed; no production previews were required or created for this inventory-only task. Planned evidence paths are explicitly future targets.', '']
 write(TASK/'verification_v001.md','\n'.join(result))
 print('\n'.join(f'{state}: {message}' for state,message in checks))
 return all(s=='PASS' for s,_ in checks)

if __name__=='__main__':
 if '--verify' in sys.argv: sys.exit(0 if verify() else 1)
